style.css:
/* =========================================
   ROSES NOIRES — DARK BURGUNDY THEME
   Black • Deep Burgundy • Ivory • Flowers
   ========================================= */

:root {
    color-scheme: dark;

    --rn-black: #090608;
    --rn-dark: #10090d;
    --rn-panel: #170c12;
    --rn-burgundy: #240008;
    --rn-wine: #4a0715;
    --rn-red: #651329;
    --rn-rose: #a99196;
    --rn-ivory: #f3e9ea;
}

/* Main surfaces */
html, body {
    scrollbar-color: #4a0715 #090608;
}

/* Selection */
::selection {
    background: #4a0715 !important;
    color: #f3e9ea !important;
}

/* Scrollbars */
::-webkit-scrollbar {
    width: 9px;
    height: 9px;
}

::-webkit-scrollbar-track {
    background: #090608;
}

::-webkit-scrollbar-thumb {
    background: #4a0715;
    border: 2px solid #090608;
    border-radius: 20px;
}

::-webkit-scrollbar-thumb:hover {
    background: #651329;
}

/* Text fields */
input, textarea, select {
    accent-color: #651329;
}

/* Buttons */
button {
    accent-color: #651329;
}

/* Links */
a {
    text-decoration-color: #651329;
    text-underline-offset: 3px;
}

/* Focus */
:focus-visible {
    outline: 1px solid #8c3048 !important;
    outline-offset: 3px;
}

/* Images remain untouched */
img, video, picture, canvas {
    filter: none !important;
}

/* Subtle floral selection details */
blockquote {
    border-left: 2px solid #4a0715 !important;
}

/* Elegant scrollbar transitions */
::-webkit-scrollbar-thumb {
    transition: background 0.25s ease;
}
